export interface Receipt { id: number; tenant: string; key: string; cents: number }

export class Ledger {
  readonly entries: Receipt[] = [];
  private readonly receiptsByKey = new Map<string, Receipt>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Check-and-insert is synchronous, so concurrent callers cannot both
    // observe a miss for the same tenant/key. A key is bound to the first
    // amount applied under it; later amounts are rejected without a debit.
    const lookup = JSON.stringify([tenant, key]);
    const existing = this.receiptsByKey.get(lookup);
    if (existing !== undefined) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.receiptsByKey.set(lookup, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}
