const assert = require('node:assert/strict');

const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Ledger: repeated equal amount returns the original receipt, no new debit.
  {
    const ledger = new Ledger();
    const a = await ledger.apply('shop', 'sale', 100);
    const b = await ledger.apply('shop', 'sale', 100);
    assert.equal(a, b);
    assert.deepEqual(a, { id: 1, tenant: 'shop', key: 'sale', cents: 100 });
    assert.equal(ledger.entries.length, 1);
  }

  // Ledger: same tenant/key with another amount conflicts without a debit.
  {
    const ledger = new Ledger();
    await ledger.apply('shop', 'sale', 100);
    await assert.rejects(ledger.apply('shop', 'sale', 200), /^Error: key conflict$/);
    assert.equal(ledger.entries.length, 1);
    // Different tenant or key is independent.
    assert.equal((await ledger.apply('shop2', 'sale', 200)).id, 2);
    assert.equal((await ledger.apply('shop', 'sale2', 200)).id, 3);
    assert.equal(ledger.entries.length, 3);
  }

  // Ledger: concurrent equal applies produce one debit and the same receipt.
  {
    const ledger = new Ledger();
    const results = await Promise.all([
      ledger.apply('t', 'k', 7),
      ledger.apply('t', 'k', 7),
      ledger.apply('t', 'k', 7),
    ]);
    assert.equal(ledger.entries.length, 1);
    assert.equal(results[0], results[1]);
    assert.equal(results[1], results[2]);
  }

  // Service: transient acks are retried, same receipt forwarded, one debit.
  {
    const ledger = new Ledger();
    const acked = [];
    let failures = 2;
    const service = new PaymentService(ledger, {
      acknowledge: async (r) => {
        acked.push(r);
        if (failures-- > 0) throw new Transient('try again');
      },
    });
    const receipt = await service.pay('shop', 'sale', 123, 3);
    assert.equal(acked.length, 3);
    assert.equal(acked[0], receipt);
    assert.equal(acked[1], receipt);
    assert.equal(acked[2], receipt);
    assert.equal(ledger.entries.length, 1);
  }

  // Service: exhausted retries rethrow the final Transient with no extra debit.
  {
    const ledger = new Ledger();
    const errors = [new Transient('a'), new Transient('b')];
    let calls = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { throw errors[calls++]; },
    });
    await assert.rejects(service.pay('t', 'k', 5, 2), (e) => e === errors[1]);
    assert.equal(calls, 2);
    assert.equal(ledger.entries.length, 1);
  }

  // Service: non-transient errors are not retried and propagate unchanged.
  {
    const ledger = new Ledger();
    const boom = new Error('boom');
    let acks = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { acks++; throw boom; },
    });
    await assert.rejects(service.pay('t', 'k', 5, 5), (e) => e === boom);
    assert.equal(acks, 1);
    assert.equal(ledger.entries.length, 1);
  }

  // Service: key conflict propagates without a second debit or any ack.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    await service.pay('shop', 'sale', 100);
    await assert.rejects(service.pay('shop', 'sale', 200), /key conflict/);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks, 1);
  }

  // Service: concurrent same-payment calls share one receipt and one debit.
  {
    const ledger = new Ledger();
    const acked = [];
    let gate;
    const ready = new Promise((resolve) => { gate = resolve; });
    const service = new PaymentService(ledger, {
      acknowledge: async (r) => {
        acked.push(r);
        if (acked.length === 2) gate();
        await ready;
      },
    });
    const [r1, r2] = await Promise.all([
      service.pay('shop', 'sale', 42),
      service.pay('shop', 'sale', 42),
    ]);
    assert.equal(r1, r2);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acked.length, 2);
    assert.equal(acked[0], r1);
    assert.equal(acked[1], r1);
  }

  // Service: invalid input throws before any ledger or transport action.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const invalid = [
      () => service.pay('', 'k', 10),
      () => service.pay('t', '', 10),
      () => service.pay('t', 'k', 0),
      () => service.pay('t', 'k', -5),
      () => service.pay('t', 'k', 1.5),
      () => service.pay('t', 'k', NaN),
      () => service.pay('t', 'k', 10, 0),
      () => service.pay('t', 'k', 10, 6),
      () => service.pay('t', 'k', 10, 2.5),
      () => service.pay('t', 'k', 10, NaN),
    ];
    for (const fn of invalid) {
      await assert.rejects(fn, /invalid payment/);
    }
    assert.equal(ledger.entries.length, 0);
    assert.equal(acks, 0);
  }

  console.log('idempotency checks OK');
}

module.exports = main();
EOF
